20|        if let previewSessionURL {
21|            try? FileManager.default.removeItem(at: previewSessionURL)
22|        }
23|    }
24|
25|    func open(url: URL) async throws -> ArchiveDocumentSnapshot {
26|        try resetPreviewSession()
27|        let accessed = url.startAccessingSecurityScopedResource()
28|        defer {
29|            if accessed { url.stopAccessingSecurityScopedResource() }
30|        }
31|        return try await provider.open(url: url)
32|    }
