34|    func materializePreview(entryID: ArchiveEntryID) async throws -> URL {
35|        try Task.checkCancellation()
36|        guard let previewSessionURL else { throw ArchiveError.helperFailed }
37|        if let activePreviewRootURL {
38|            try? FileManager.default.removeItem(at: activePreviewRootURL)
39|        }
40|        let requestRoot = previewSessionURL.appending(
41|            path: UUID().uuidString,
42|            directoryHint: .isDirectory
43|        )
44|        try FileManager.default.createDirectory(
45|            at: requestRoot,
46|            withIntermediateDirectories: false,
47|            attributes: [.posixPermissions: 0o700]
48|        )
49|        activePreviewRootURL = requestRoot
50|        do {
51|            try Task.checkCancellation()
52|            let materializedURL = try await provider.materializeEntry(id: entryID, under: requestRoot)
53|            try Task.checkCancellation()
54|            return materializedURL
55|        } catch {
56|            try? FileManager.default.removeItem(at: requestRoot)
57|            activePreviewRootURL = nil
58|            throw error
59|        }
60|    }
61|
62|    private func resetPreviewSession() throws {
63|        let root = ValidatedPreviewCacheURL.cacheRoot
64|        if let previewSessionURL {
65|            try? FileManager.default.removeItem(at: previewSessionURL)
66|        }
67|        try FileManager.default.createDirectory(
68|            at: root,
69|            withIntermediateDirectories: true,
70|            attributes: [.posixPermissions: 0o700]
71|        )
72|        try? FileManager.default.setAttributes([.posixPermissions: 0o700], ofItemAtPath: root.path)
73|        let session = root.appending(path: UUID().uuidString, directoryHint: .isDirectory)
74|        try FileManager.default.createDirectory(
75|            at: session,
76|            withIntermediateDirectories: false,
77|            attributes: [.posixPermissions: 0o700]
78|        )
79|        previewSessionURL = session
