26|struct PreviewRoutingPolicy: Sendable {
27|    func kind(forFilename filename: String) -> PreviewKind {
28|        let fileExtension = URL(fileURLWithPath: filename).pathExtension.lowercased()
29|        switch fileExtension {
30|        case "png", "jpg", "jpeg", "heic", "gif", "tif", "tiff", "bmp", "webp", "svg":
31|            return .image
32|        case "mp4", "mov", "m4v":
33|            return .video
34|        case "pdf":
35|            return .pdfKit
36|        case "doc", "docx":
37|            return .quickLookOffice(.word)
38|        case "xls", "xlsx":
39|            return .quickLookOffice(.excel)
40|        case "ppt", "pptx":
41|            return .quickLookOffice(.powerPoint)
42|        default:
43|            return .unsupported
44|        }
45|    }
