148|        for element in elements {
149|            guard let virtualElement = element as? NSObject,
150|                  virtualElement.responds(to: NSSelectorFromString("accessibilityLabel")) else { continue }
151|            let role = virtualElement.value(forKey: "accessibilityRole") as? String
152|            let label = virtualElement.value(forKey: "accessibilityLabel") as? String
153|            if label?.isEmpty != false, let fallback = fallbackLabel(forRole: role, pageCount: pageCount) {
154|                virtualElement.setValue(fallback, forKey: "accessibilityLabel")
155|            }
156|            let children = virtualElement.value(forKey: "accessibilityChildren") as? [Any] ?? []
157|            labelPDFVirtualElements(children, pageCount: pageCount)
158|        }
