2|import ArchiveSecurity
3|import CMinizipBridge
4|import Foundation
5|
6|public actor ZIPArchiveProvider: ArchiveProvider {
7|    private let listingEntryLimit: Int
8|    private var reader: ZIPBridgeReader?
9|    private var entriesByID: [ArchiveEntryID: ArchiveEntrySnapshot] = [:]
10|    private var ordinalsByID: [ArchiveEntryID: UInt64] = [:]
11|
12|    public init() {
13|        listingEntryLimit = 1_000_000
14|    }
15|
16|    init(listingEntryLimit: Int) {
17|        self.listingEntryLimit = listingEntryLimit
18|    }
19|
20|    public func open(url: URL) throws -> ArchiveDocumentSnapshot {
21|        reader = nil
22|        entriesByID = [:]
23|        ordinalsByID = [:]
24|
25|        let openedReader = try ZIPBridgeReader(url: url)
26|        let bridgeEntries = try openedReader.allEntries(maximumCount: listingEntryLimit)
27|        var snapshots: [ArchiveEntrySnapshot] = []
28|        snapshots.reserveCapacity(bridgeEntries.count)
29|
30|        for bridgeEntry in bridgeEntries {
31|            guard let displayPath = String(bytes: bridgeEntry.nameBytes, encoding: .utf8) else {
32|                throw ArchiveError.unsupportedFormat
33|            }
34|            let validationPath = bridgeEntry.isDirectory && displayPath.hasSuffix("/")
35|                ? String(displayPath.dropLast())
36|                : displayPath
37|            do {
38|                try ArchivePathPolicy().validate(validationPath)
39|            } catch {
40|                throw ArchiveError.unsafePath
41|            }
42|
43|            let entry = ArchiveEntry(
44|                id: ArchiveEntryID(),
45|                rawPath: ArchivePathBytes(bridgeEntry.nameBytes),
46|                displayPath: displayPath
47|            )
48|            snapshots.append(ArchiveEntrySnapshot(
49|                entry: entry,
50|                compressedSize: bridgeEntry.compressedSize,
51|                uncompressedSize: bridgeEntry.uncompressedSize,
52|                modifiedAt: bridgeEntry.modifiedAt,
53|                isDirectory: bridgeEntry.isDirectory,
54|                isSymbolicLink: bridgeEntry.isSymbolicLink,
55|                isEncrypted: bridgeEntry.isEncrypted,
56|                usesUTF8FileName: bridgeEntry.usesUTF8FileName
57|            ))
58|        }
59|
60|        reader = openedReader
61|        entriesByID = Dictionary(uniqueKeysWithValues: snapshots.map { ($0.entry.id, $0) })
62|        ordinalsByID = Dictionary(uniqueKeysWithValues: snapshots.enumerated().map {
63|            ($0.element.entry.id, UInt64($0.offset))
64|        })
65|        return ArchiveDocumentSnapshot(sourceURL: url, format: .zip, entries: snapshots)
66|    }
67|
68|    public func readEntry(id: ArchiveEntryID, maximumBytes: UInt64) throws -> Data {
69|        guard
70|            let snapshot = entriesByID[id],
71|            let ordinal = ordinalsByID[id],
72|            let reader
73|        else {
74|            throw ArchiveError.helperFailed
75|        }
76|        guard !snapshot.isDirectory, !snapshot.isSymbolicLink else {
77|            throw ArchiveError.unsafePath
78|        }
79|        guard !snapshot.isEncrypted else {
80|            throw ArchiveError.passwordRequired
81|        }
82|        guard snapshot.uncompressedSize <= maximumBytes,
83|              snapshot.uncompressedSize <= UInt64(Int.max) else {
84|            throw ArchiveError.resourceLimit
85|        }
86|        return try reader.readEntry(
87|            ordinal: ordinal,
88|            expectedSize: snapshot.uncompressedSize,
89|            maximumBytes: maximumBytes
90|        )
91|    }
92|
93|    public func materializeEntry(
94|        id: ArchiveEntryID,
95|        under rootURL: URL,
96|        budget: ResourceBudget = .previewDefault
97|    ) throws -> URL {
98|        try Task.checkCancellation()
99|        guard let snapshot = entriesByID[id] else {
100|            throw ArchiveError.helperFailed
101|        }
102|        let decision = budget.evaluate(ResourceEstimate(
103|            compressedBytes: snapshot.compressedSize,
104|            expandedBytes: snapshot.uncompressedSize,
105|            entries: 1,
106|            depth: 1
107|        ))
108|        guard decision == .allow else { throw ArchiveError.resourceLimit }
109|        let data = try readEntry(id: id, maximumBytes: budget.maxExpandedBytes)
110|        try Task.checkCancellation()
111|        let output = try SecureFileMaterializer(rootURL: rootURL).write(
112|            data,
113|            relativePath: snapshot.entry.displayPath
114|        )
115|        try Task.checkCancellation()
116|        return output
117|    }
118|}
119|
120|private struct ZIPBridgeEntry {
121|    let nameBytes: [UInt8]
122|    let compressedSize: UInt64
123|    let uncompressedSize: UInt64
124|    let modifiedAt: Date?
125|    let isDirectory: Bool
126|    let isSymbolicLink: Bool
127|    let isEncrypted: Bool
128|    let usesUTF8FileName: Bool
129|}
130|
131|private final class ZIPBridgeReader {
132|    private var handle: OpaquePointer?
133|
134|    init(url: URL) throws {
135|        var opened: OpaquePointer?
136|        let status = url.withUnsafeFileSystemRepresentation { path in
137|            guard let path else { return Int32(AWB_MZ_INVALID_ARGUMENT) }
138|            return awb_mz_reader_open(path, &opened)
139|        }
140|        guard status == AWB_MZ_OK, let opened else {
141|            throw ZIPProviderErrorMapper.archiveError(for: status)
142|        }
143|        handle = opened
144|    }
145|
146|    deinit {
147|        awb_mz_reader_close(&handle)
148|    }
149|
150|    func allEntries(maximumCount: Int) throws -> [ZIPBridgeEntry] {
151|        guard let handle else { throw ArchiveError.helperFailed }
152|        guard maximumCount > 0 else { throw ArchiveError.resourceLimit }
153|        var result: [ZIPBridgeEntry] = []
154|        var info = awb_mz_entry_info()
155|        var status = awb_mz_reader_first(handle, &info)
156|        while status == AWB_MZ_OK {
157|            guard result.count < maximumCount else {
158|                throw ArchiveError.resourceLimit
159|            }
160|            result.append(try copy(info))
161|            status = awb_mz_reader_next(handle, &info)
162|        }
163|        guard status == AWB_MZ_END else {
164|            throw ZIPProviderErrorMapper.archiveError(for: status)
165|        }
166|        return result
167|    }
168|
169|    func readEntry(ordinal: UInt64, expectedSize: UInt64, maximumBytes: UInt64) throws -> Data {
170|        guard let handle else { throw ArchiveError.helperFailed }
171|        var info = awb_mz_entry_info()
172|        var status = awb_mz_reader_goto(handle, ordinal, &info)
173|        guard status == AWB_MZ_OK else {
174|            throw ZIPProviderErrorMapper.archiveError(for: status)
175|        }
176|        status = awb_mz_reader_open_current(handle)
177|        guard status == AWB_MZ_OK else {
178|            throw ZIPProviderErrorMapper.archiveError(for: status)
179|        }
180|
181|        var data = Data()
182|        data.reserveCapacity(Int(expectedSize))
183|        var buffer = [UInt8](repeating: 0, count: 64 * 1024)
184|        var readError: ArchiveError?
185|        while true {
186|            let count = buffer.withUnsafeMutableBufferPointer { bytes in
187|                awb_mz_reader_read_current(handle, bytes.baseAddress, Int32(bytes.count))
188|            }
189|            if count == 0 { break }
190|            if count < 0 {
191|                readError = ZIPProviderErrorMapper.archiveError(for: count)
192|                break
193|            }
194|            let nextSize = UInt64(data.count) + UInt64(count)
195|            if nextSize > maximumBytes {
196|                readError = .resourceLimit
197|                break
198|            }
199|            data.append(buffer, count: Int(count))
200|        }
201|
202|        let closeStatus = awb_mz_reader_close_current(handle)
203|        if let readError { throw readError }
204|        guard closeStatus == AWB_MZ_OK else {
205|            throw ZIPProviderErrorMapper.archiveError(for: closeStatus)
206|        }
207|        guard UInt64(data.count) == expectedSize else {
208|            throw ArchiveError.corruptedArchive
209|        }
210|        return data
211|    }
212|
213|    private func copy(_ info: awb_mz_entry_info) throws -> ZIPBridgeEntry {
214|        guard let nameBytes = info.name_bytes, info.name_size > 0 else {
215|            throw ArchiveError.corruptedArchive
216|        }
217|        let name = Array(UnsafeBufferPointer(start: nameBytes, count: Int(info.name_size)))
218|        return ZIPBridgeEntry(
219|            nameBytes: name,
220|            compressedSize: info.compressed_size,
221|            uncompressedSize: info.uncompressed_size,
222|            modifiedAt: info.modified_unix_time > 0
223|                ? Date(timeIntervalSince1970: TimeInterval(info.modified_unix_time))
224|                : nil,
225|            isDirectory: info.is_directory != 0,
226|            isSymbolicLink: info.is_symlink != 0,
227|            isEncrypted: info.is_encrypted != 0,
228|            usesUTF8FileName: info.uses_utf8_file_name != 0
229|        )
230|    }
231|}
