4|public enum SecureMaterializationError: Error, Equatable, Sendable {
5|    case invalidRoot
6|    case fileExists
7|    case io(Int32)
8|}
9|
10|public struct SecureFileMaterializer: Sendable {
11|    public let rootURL: URL
12|
13|    public init(rootURL: URL) {
14|        self.rootURL = rootURL
15|    }
16|
17|    public func write(_ data: Data, relativePath: String) throws -> URL {
18|        try ArchivePathPolicy().validate(relativePath)
19|        let components = relativePath.split(separator: "/", omittingEmptySubsequences: false).map(String.init)
20|        guard let leaf = components.last else {
21|            throw ArchiveSecurityError.emptyComponent
22|        }
23|
24|        let rootFD = rootURL.withUnsafeFileSystemRepresentation { path -> Int32 in
25|            guard let path else { return -1 }
26|            return Darwin.open(path, O_RDONLY | O_DIRECTORY | O_CLOEXEC | O_NOFOLLOW)
27|        }
28|        guard rootFD >= 0 else {
29|            throw SecureMaterializationError.invalidRoot
30|        }
31|
32|        var directoryDescriptors = [rootFD]
33|        defer {
34|            for descriptor in directoryDescriptors.reversed() {
35|                Darwin.close(descriptor)
36|            }
37|        }
38|
39|        var parentFD = rootFD
40|        for component in components.dropLast() {
41|            let mkdirResult = component.withCString { name in
42|                mkdirat(parentFD, name, mode_t(0o700))
43|            }
44|            if mkdirResult != 0 && errno != EEXIST {
45|                throw SecureMaterializationError.io(errno)
46|            }
47|            let childFD = component.withCString { name in
48|                openat(parentFD, name, O_RDONLY | O_DIRECTORY | O_CLOEXEC | O_NOFOLLOW)
49|            }
50|            guard childFD >= 0 else {
51|                throw SecureMaterializationError.io(errno)
52|            }
53|            directoryDescriptors.append(childFD)
54|            parentFD = childFD
55|        }
56|
57|        var leafFD = leaf.withCString { name in
58|            openat(
59|                parentFD,
60|                name,
61|                O_WRONLY | O_CREAT | O_EXCL | O_CLOEXEC | O_NOFOLLOW,
62|                mode_t(0o600)
63|            )
64|        }
65|        guard leafFD >= 0 else {
66|            if errno == EEXIST { throw SecureMaterializationError.fileExists }
67|            throw SecureMaterializationError.io(errno)
68|        }
69|
70|        var published = false
71|        defer {
72|            if leafFD >= 0 { Darwin.close(leafFD) }
73|            if !published {
74|                _ = leaf.withCString { name in unlinkat(parentFD, name, 0) }
75|            }
76|        }
77|
78|        try data.withUnsafeBytes { bytes in
79|            var offset = 0
80|            while offset < bytes.count {
81|                guard let baseAddress = bytes.baseAddress else { break }
82|                let result = Darwin.write(
83|                    leafFD,
84|                    baseAddress.advanced(by: offset),
85|                    bytes.count - offset
86|                )
87|                if result < 0 {
88|                    if errno == EINTR { continue }
89|                    throw SecureMaterializationError.io(errno)
90|                }
91|                guard result > 0 else {
92|                    throw SecureMaterializationError.io(EIO)
93|                }
94|                offset += result
95|            }
96|        }
97|
98|        guard fsync(leafFD) == 0 else {
99|            throw SecureMaterializationError.io(errno)
100|        }
101|        guard Darwin.close(leafFD) == 0 else {
102|            leafFD = -1
103|            throw SecureMaterializationError.io(errno)
104|        }
105|        leafFD = -1
106|        guard fsync(parentFD) == 0 else {
107|            throw SecureMaterializationError.io(errno)
108|        }
109|        published = true
110|        return rootURL.appending(path: relativePath)
111|    }
112|}
